const request = require('supertest');
const app = require('./app');

describe('POST /users – input validation', () => {
  // ── 400 cases ──────────────────────────────────────────────────────────────

  test('rejects a request with no body at all', async () => {
    const res = await request(app).post('/users').send();
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/missing required field: name/i);
  });

  test('rejects a request whose body omits the name field', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send({ email: 'charlie@example.com' });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/missing required field: name/i);
  });

  test('rejects an explicit null name', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send({ name: null });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/missing required field: name/i);
  });

  test('rejects a numeric name', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send({ name: 42 });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid type: name must be a string/i);
  });

  test('rejects a boolean name', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send({ name: true });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid type: name must be a string/i);
  });

  test('rejects an array as name', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send({ name: ['Alice'] });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid type: name must be a string/i);
  });

  test('rejects an object as name', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send({ name: { first: 'Alice' } });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid type: name must be a string/i);
  });

  test('rejects a blank (whitespace-only) name', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send({ name: '   ' });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid value: name must not be blank/i);
  });

  // ── 201 cases ──────────────────────────────────────────────────────────────

  test('accepts a valid name and returns 201 with the new user', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send({ name: 'Charlie' });
    expect(res.status).toBe(201);
    expect(res.body).toMatchObject({ name: 'Charlie' });
    expect(typeof res.body.id).toBe('number');
  });

  test('trims surrounding whitespace from a valid name', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send({ name: '  Dana  ' });
    expect(res.status).toBe(201);
    expect(res.body.name).toBe('Dana');
  });
});

