const request = require('supertest');
const app = require('./app');

describe('POST /users – input validation', () => {
  // ── 400 cases ──────────────────────────────────────────────────────────────

  test('rejects a request with no body (name absent)', async () => {
    const res = await request(app).post('/users').send({});
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/missing required field: name/i);
  });

  test('rejects when name is explicitly null', async () => {
    const res = await request(app).post('/users').send({ name: null });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/missing required field: name/i);
  });

  test('rejects when name is a number', async () => {
    const res = await request(app).post('/users').send({ name: 42 });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid type: name must be a string/i);
  });

  test('rejects when name is a boolean', async () => {
    const res = await request(app).post('/users').send({ name: true });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid type: name must be a string/i);
  });

  test('rejects when name is an object', async () => {
    const res = await request(app).post('/users').send({ name: {} });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid type: name must be a string/i);
  });

  test('rejects when name is an array', async () => {
    const res = await request(app).post('/users').send({ name: [] });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid type: name must be a string/i);
  });

  test('rejects when name is a blank string', async () => {
    const res = await request(app).post('/users').send({ name: '   ' });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid value: name must not be blank/i);
  });

  test('rejects when name is an empty string', async () => {
    const res = await request(app).post('/users').send({ name: '' });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/invalid value: name must not be blank/i);
  });

  // ── 201 cases ──────────────────────────────────────────────────────────────

  test('accepts a valid name and returns 201', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: 'Alice' });
    expect(res.status).toBe(201);
    expect(res.body).toEqual({ message: 'User created', name: 'Alice' });
  });

  test('trims surrounding whitespace from a valid name', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: '  Bob  ' });
    expect(res.status).toBe(201);
    expect(res.body).toEqual({ message: 'User created', name: 'Bob' });
  });
});

